content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-15-smart-home-010

=== 用户原始指令 (query.txt) ===
给我列个安检清单能打勾,点一下跳进去,显示天气,已连接

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我列个安检清单能打勾,点一下跳进去,显示天气,已连接",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称",
            "sampleValue": "朝阳区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "24°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          }
        }
      }
    },
    "checklist": {
      "title": {
        "type": "string",
        "description": "智能家居安检清单标题",
        "sampleValue": "安检清单"
      },
      "items": [
        {
          "label": {
            "type": "string",
            "description": "第一项安检事项",
            "sampleValue": "门窗已锁"
          },
          "value": {
            "type": "string",
            "description": "第一项安检值",
            "sampleValue": "doors"
          },
          "select": {
            "type": "boolean",
            "description": "第一项是否已勾选",
            "sampleValue": true
          }
        },
        {
          "label": {
            "type": "string",
            "description": "第二项安检事项",
            "sampleValue": "燃气已关"
          },
          "value": {
            "type": "string",
            "description": "第二项安检值",
            "sampleValue": "gas"
          },
          "select": {
            "type": "boolean",
            "description": "第二项是否已勾选",
            "sampleValue": true
          }
        },
        {
          "label": {
            "type": "string",
            "description": "第三项安检事项",
            "sampleValue": "灯具已检"
          },
          "value": {
            "type": "string",
            "description": "第三项安检值",
            "sampleValue": "lights"
          },
          "select": {
            "type": "boolean",
            "description": "第三项是否已勾选",
            "sampleValue": false
          }
        }
      ]
    },
    "connection": {
      "statusText": {
        "type": "string",
        "description": "智能家居连接状态展示文本",
        "sampleValue": "已连接"
      }
    },
    "actions": {
      "weatherLabel": {
        "type": "string",
        "description": "进入天气详情的短动作文案",
        "sampleValue": "看天气"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/house_fill.svg",
      "description": "房屋实心图标，适合表达智能家居入口和家庭安检对象。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色多云天气图标，适合表达当前天气状态。"
    }
  ]
}

